import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color,
  } = THREE;

  const root = new Group();
  root.name = 'cta-label';
  root.userData.handlers = {};

  const resources = [];
  const primitiveResults = [];
  let alive = true;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: visualSpec.colors?.ink ?? '#16161d',
    paper: visualSpec.colors?.paper ?? '#e8ecf2',
    accent: visualSpec.colors?.accent ?? '#ff2a38',
    surface: visualSpec.colors?.surface ?? '#0b0b10',
  };

  const hexToVec3 = (hex) => {
    const color = new Color(hex);
    return vec3(color.r, color.g, color.b);
  };

  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropY = uv().y;
  const surfaceNode = hexToVec3(colors.surface);
  const inkNode = hexToVec3(colors.ink);
  const backdropMid = mix(surfaceNode, inkNode, smoothstep(0.0, 0.58, backdropY));
  backdropMaterial.colorNode = mix(
    backdropMid,
    vec3(0.16, 0.16, 0.19),
    smoothstep(0.58, 1.0, backdropY),
  );

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6),
    backdropMaterial,
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  const shadow = new Mesh(
    new CircleGeometry(1.9, 48),
    shadowMaterial,
  );
  shadow.name = 'cta-contact-shadow';
  shadow.scale.set(1.65, 0.22, 1);
  shadow.position.set(0, -0.57, -0.08);
  root.add(shadow);
  resources.push(shadow.geometry, shadow.material);

  const panelGeometry = new BoxGeometry(3.7, 0.86, 0.16, 4, 2, 2);
  const panelMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.name = 'machined-metal-cta';
  panel.position.z = 0.08;
  root.add(panel);
  resources.push(panel.geometry, panel.material);

  const highlightMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.18,
  });
  const highlight = new Mesh(
    new PlaneGeometry(3.28, 0.018),
    highlightMaterial,
  );
  highlight.name = 'machined-edge-highlight';
  highlight.position.set(0, 0.335, 0.19);
  root.add(highlight);
  resources.push(highlight.geometry, highlight.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
  });
  const accentBar = new Mesh(
    new BoxGeometry(0.07, 0.58, 0.035),
    accentMaterial,
  );
  accentBar.name = 'signal-red-accent';
  accentBar.position.set(-1.52, 0, 0.2);
  root.add(accentBar);
  resources.push(accentBar.geometry, accentBar.material);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 42,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: item.typography?.letterSpacingPx,
      maxWidthPx: item.typography?.maxWidthPx,
    });
    textObject.name = item.role ? `cta-text-${item.role}` : 'cta-text';
    textObject.position.set(0.04, -0.02, 0.205);
    root.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!alive) return;
      panelMaterial.map = texture;
      panelMaterial.needsUpdate = true;
      if ('colorSpace' in texture && THREE.SRGBColorSpace) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }
      resources.push(texture);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive !== 'function') continue;
    const result = applyPrimitive(root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.cleanup = () => {
    alive = false;

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.userData.handlers = {};
  };

  return root;
}
